import { writeFileSync } from "node:fs";
import path from "node:path";

import { expect, expectStatus, sample, test } from "../../fixtures";

test("An expired insurance certificate cannot be approved", { tag: "@REV-07" }, async ({ apiAs, factory }, testInfo) => {
  // Arrange: an insurance certificate that expired yesterday (the API compares against the UTC date).
  const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
  const certificate = testInfo.outputPath("insurance_certificate_expired.txt");
  writeFileSync(
    certificate,
    `Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: ${yesterday}\n`,
  );
  const { documents, extractions } = await factory.vendorInReview({
    files: { insurance_certificate: path.relative(sample(""), certificate) },
  });
  const reviewer = await apiAs("reviewer");

  // Act
  const response = await reviewer.post(`/api/extractions/${extractions.insurance_certificate.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("insurance_expired");
  expect((await factory.extraction(documents.insurance_certificate.id, "reviewer")).status).toBe("pending_review");
});
